import math

# Hardcoded constants and given values
r = 5.0          # Resistance of each resistor in Ohms
R_target = 3.0   # Target total resistance in Ohms

# Dictionary to store achievable resistance ratios for n resistors
# Key: n (number of resistors), Value: set of achievable resistance values
S = {1: {r}}

def main():
    found_n = None

    # Iterate to find the minimum n
    for n in range(2, 20):
        S[n] = set()
        # Try all splits of n resistors into i and j groups
        for i in range(1, n):
            j = n - i
            for val_a in S[i]:
                for val_b in S[j]:
                    # Series combination: R_eq = R1 + R2
                    R_series = val_a + val_b
                    S[n].add(R_series)

                    # Parallel combination: 1/R_eq = 1/R1 + 1/R2 => R_eq = (R1*R2)/(R1+R2)
                    if val_a + val_b != 0:
                        R_parallel = (val_a * val_b) / (val_a + val_b)
                        S[n].add(R_parallel)

        # Check if target is found
        if R_target in S[n]:
            found_n = n
            break

    if found_n is not None:
        print(f"FINAL ANSWER: {found_n}")
        print("UNIT: resistors")
    else:
        print("FINAL ANSWER: not found")
        print("UNIT: resistors")

if __name__ == "__main__":
    main()
